mapper.select:
SELECT SQL_CALC_FOUND_ROWS board_no , board_title, board_writer, board_userName, board_categoryMain, board_categoryMid, board_categorySub, board_changeThumbnail, board_content , board_hit , board_like , board_hate , board_date ,board_imgList, (SELECT COUNT(*) FROM board_comment c WHERE c.board_no = board.board_no) AS commentCount FROM board
AND board_title LIKE concat('%' , #{searchWord} , '%')
AND board_content LIKE concat('%' , #{searchWord} , '%')
AND (board_title LIKE concat('%' , #{searchWord} , '%') OR board_content LIKE concat('%' , #{searchWord} , '%'))
AND board_categoryMain = #{categoryMain}
AND board_categoryMid = #{categoryMid}
AND board_categorySub = #{categorySub}
LIMIT #{scrollIndex}, 6

